mapper.insert:
INSERT INTO authority_diagnosis_source (
    source_id, investigation_id, aggregate_version, contract_version,
    source_json, source_sha256, document_sha256, committed_at
) VALUES (
    #{sourceId}, #{investigationId}, #{aggregateVersion}, #{contractVersion},
    #{sourceJson}, #{sourceSha256}, #{documentSha256}, #{committedAt}
)

INSERT INTO authority_publication_intent (
    intent_id, investigation_id, aggregate_sequence, event_type, source_id,
    source_sha256, topic_name, idempotency_key, schema_version, canonical_content,
    canonical_sha256, status, attempt_count, eligible_at, created_at, updated_at
) VALUES (
    #{intentId}, #{investigationId}, #{aggregateSequence}, #{eventType}, #{sourceId},
    #{sourceSha256}, #{topicName}, #{idempotencyKey}, #{schemaVersion}, #{canonicalContent},
    #{canonicalSha256}, #{status}, #{attemptCount}, #{eligibleAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT intent_id FROM authority_publication_intent
WHERE status = 'PENDING' AND eligible_at <= #{now}
ORDER BY investigation_id, aggregate_sequence, created_at LIMIT #{limit}

mapper.update:
UPDATE authority_publication_intent
SET status='IN_FLIGHT', attempt_count=attempt_count+1, lease_owner=#{owner}, lease_token=#{token},
    lease_expires_at=#{expiresAt}, updated_at=#{now}
WHERE intent_id=#{intentId} AND status='PENDING' AND eligible_at <= #{now}

UPDATE authority_publication_intent
SET status='PENDING', eligible_at=#{now}, lease_owner=NULL, lease_token=NULL, lease_expires_at=NULL,
    last_error_code='LEASE_EXPIRED', updated_at=#{now}
WHERE status='IN_FLIGHT' AND lease_expires_at <= #{now}

UPDATE authority_publication_intent
SET status='DELIVERED', delivered_at=#{now}, lease_owner=NULL, lease_token=NULL,
    lease_expires_at=NULL, last_error_code=NULL, updated_at=#{now}
WHERE intent_id=#{intentId} AND status='IN_FLIGHT' AND lease_token=#{token}
      AND lease_expires_at > #{now}

UPDATE authority_publication_intent
SET status='PENDING', eligible_at=#{eligibleAt}, lease_owner=NULL, lease_token=NULL,
    lease_expires_at=NULL, last_error_code=#{errorCode}, updated_at=#{now}
WHERE intent_id=#{intentId} AND status='IN_FLIGHT' AND lease_token=#{token}
      AND lease_expires_at > #{now}

UPDATE authority_publication_intent
SET status='DEAD', lease_owner=NULL, lease_token=NULL, lease_expires_at=NULL,
    last_error_code=#{errorCode}, updated_at=#{now}
WHERE intent_id=#{intentId} AND status='IN_FLIGHT' AND lease_token=#{token}
      AND lease_expires_at > #{now}
